CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE ROLE source_app LOGIN PASSWORD 'source-local';
CREATE ROLE cdc_user LOGIN REPLICATION PASSWORD 'cdc-local';
CREATE ROLE source_reader LOGIN PASSWORD 'reader-local';
CREATE SCHEMA trading;
SET search_path TO trading,public;
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers(id),currency text NOT NULL CHECK(currency IN ('USD','GBP','EUR')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','closed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_balances(id uuid PRIMARY KEY REFERENCES accounts(id),cash_minor bigint NOT NULL DEFAULT 0 CHECK(cash_minor BETWEEN 0 AND 1000000000000000),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE instruments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),symbol text NOT NULL UNIQUE,currency text NOT NULL CHECK(currency IN ('USD','GBP','EUR')));
INSERT INTO instruments(id,symbol,currency) VALUES ('00000000-0000-4000-8000-000000000001','SYNTH-ALPHA','USD'),('00000000-0000-4000-8000-000000000002','SYNTH-BETA','USD'),('00000000-0000-4000-8000-000000000003','SYNTH-GAMMA','GBP');
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),instrument_id uuid NOT NULL REFERENCES instruments(id),side text NOT NULL CHECK(side IN ('buy','sell')),quantity bigint NOT NULL CHECK(quantity BETWEEN 1 AND 1000000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sequence_id bigserial UNIQUE NOT NULL,execution_ref text NOT NULL UNIQUE,order_id uuid NOT NULL REFERENCES orders(id),account_id uuid NOT NULL REFERENCES accounts(id),instrument_id uuid NOT NULL REFERENCES instruments(id),side text NOT NULL CHECK(side IN ('buy','sell')),quantity bigint NOT NULL CHECK(quantity BETWEEN 1 AND 1000000),price_minor bigint NOT NULL CHECK(price_minor BETWEEN 1 AND 1000000000),notional_minor bigint NOT NULL CHECK(notional_minor=quantity*price_minor),currency text NOT NULL CHECK(currency IN ('USD','GBP','EUR')),fee_minor bigint NOT NULL CHECK(fee_minor BETWEEN 0 AND 1000000000),reversed boolean NOT NULL DEFAULT false,occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sequence_id bigserial UNIQUE NOT NULL,account_id uuid NOT NULL REFERENCES accounts(id),kind text NOT NULL CHECK(kind IN ('deposit','withdrawal','execution','reversal')),amount_minor bigint NOT NULL,currency text NOT NULL CHECK(currency IN ('USD','GBP','EUR')),execution_id uuid REFERENCES executions(id),reversal_of uuid UNIQUE REFERENCES account_transactions(id),occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='reversal')=(reversal_of IS NOT NULL)));
CREATE TABLE deposits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),transaction_id uuid UNIQUE NOT NULL REFERENCES account_transactions(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),occurred_at timestamptz NOT NULL);
CREATE TABLE withdrawals(LIKE deposits INCLUDING DEFAULTS INCLUDING CONSTRAINTS);
ALTER TABLE withdrawals ADD PRIMARY KEY(id),ADD FOREIGN KEY(account_id) REFERENCES accounts(id),ADD FOREIGN KEY(transaction_id) REFERENCES account_transactions(id),ADD UNIQUE(transaction_id);
CREATE TABLE fees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid UNIQUE NOT NULL REFERENCES executions(id),account_id uuid NOT NULL REFERENCES accounts(id),amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL,reversed boolean NOT NULL DEFAULT false,occurred_at timestamptz NOT NULL);
CREATE TABLE positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),instrument_id uuid NOT NULL REFERENCES instruments(id),quantity bigint NOT NULL CHECK(quantity>=0),UNIQUE(account_id,instrument_id));
CREATE TABLE position_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),instrument_id uuid NOT NULL REFERENCES instruments(id),execution_id uuid NOT NULL REFERENCES executions(id),quantity bigint NOT NULL CHECK(quantity<>0),is_reversal boolean NOT NULL DEFAULT false,occurred_at timestamptz NOT NULL,UNIQUE(execution_id,is_reversal));
CREATE TABLE price_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),instrument_id uuid NOT NULL REFERENCES instruments(id),price_minor bigint NOT NULL CHECK(price_minor>0),currency text NOT NULL,occurred_at timestamptz NOT NULL,UNIQUE(instrument_id,occurred_at));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action text NOT NULL,entity_id uuid NOT NULL,correlation_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys(key text PRIMARY KEY,request_hash text NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON executions(account_id,instrument_id,sequence_id);
CREATE INDEX ON account_transactions(account_id,sequence_id);
CREATE INDEX ON orders(account_id);
CREATE INDEX ON position_movements(account_id,instrument_id);
CREATE INDEX ON price_snapshots(instrument_id,occurred_at DESC);
CREATE INDEX ON audit_events(created_at);
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='trading' LOOP EXECUTE format('ALTER TABLE trading.%I REPLICA IDENTITY FULL',t.tablename); END LOOP; END $$;
CREATE PUBLICATION biglobal_publication FOR TABLE customers,accounts,account_balances,instruments,orders,executions,account_transactions,deposits,withdrawals,fees,positions,position_movements,price_snapshots,audit_events;
GRANT USAGE ON SCHEMA trading TO source_app,cdc_user,source_reader;
GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA trading TO source_app;
GRANT SELECT ON ALL TABLES IN SCHEMA trading TO cdc_user,source_reader;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA trading TO source_app;
ALTER ROLE source_app SET search_path=trading,public;
ALTER ROLE source_reader SET search_path=trading,public;
